mapper.sql:
SELECT summary.source_bill_no AS sourceBillNo, summary.line_count AS lineCount, summary.source_modify_time AS sourceModifyTime, summary.last_sync_time AS lastSyncTime, summary.production_order_count AS productionOrderCount, ${productionOrderSummarySql} AS productionOrderSummary FROM ( SELECT base.source_bill_no, base.tenant_id, COUNT(*) AS line_count, MAX(base.source_modify_time) AS source_modify_time, MAX(base.last_sync_time) AS last_sync_time, COUNT(DISTINCT NULLIF(base.production_order_no, '')) AS production_order_count FROM mes_kingdee_production_material_list base WHERE base.deleted = 0
AND base.source_bill_no = #{reqVO.syncCode}
GROUP BY base.source_bill_no, base.tenant_id ) summary WHERE EXISTS ( SELECT 1 FROM mes_kingdee_production_material_list matched WHERE matched.deleted = 0 AND matched.source_bill_no = summary.source_bill_no AND matched.tenant_id = summary.tenant_id
)
AND (${ew.sqlSegment})
